"""V2 mirror of the original SwapAndScale node."""
from .swap_and_scale import (
    SwapAndScale, SwapAndScaleExtension, comfy_entrypoint,
    NODE_CLASS_MAPPINGS, NODE_DISPLAY_NAME_MAPPINGS,
)

from comfy_api.latest import ComfyExtension, io

# wildcard trick is taken from pythongossss's
class AnyType(str):
    def __ne__(self, __value: object) -> bool:
        return False

any_typ = AnyType("*")

class SwapAndScale(io.ComfyNode):
    SDK_REFS = False
    SDK_PERMISSIONS = ()

    @classmethod
    def define_schema(cls) -> io.Schema:
        return io.Schema(
            node_id="SwapAndScale",
            display_name="Swap width/height and/or scale image",
            category="Image",
            inputs=[
                io.Int.Input("IN_HEIGHT"),
                io.Int.Input("IN_WIDTH"),
                io.Boolean.Input("Swap_Width_Height", default=False),
                io.Boolean.Input("factor_32px", default=True),
                io.Boolean.Input("Limit_1MP", default=True),
            ],
            outputs=[io.Int.Output("out_height"), io.Int.Output("out_width")],
            is_output_node=True,
        )

    @staticmethod
    def adjust_x32(value):
        """Lower value to closest number in factor of 32."""
        return value if value % 32 == 0 else value - (value % 32)

    def scale_values(self, IN_HEIGHT, IN_WIDTH, max_product):
        """Scale IN_HEIGHT and IN_WIDTH proportionally while keeping them multiples of 32."""
        factor = (max_product / (IN_HEIGHT * IN_WIDTH)) ** 0.5
        new_h = int(IN_HEIGHT * factor)
        new_b = int(IN_WIDTH * factor)

        return self.adjust_x32(new_h), self.adjust_x32(new_b)

    def process_inputs(self, IN_HEIGHT, IN_WIDTH, IN_swap, factor_32px, Limit_1MP):
        """Processes inputs according to the set rules."""

        # Step 1: Adjust to 32px format if selected
        if factor_32px:
            IN_HEIGHT = self.adjust_x32(IN_HEIGHT)
            IN_WIDTH = self.adjust_x32(IN_WIDTH)

        # Step 2: Check if product exceeds 1MP and adjust
        if Limit_1MP and (IN_HEIGHT * IN_WIDTH > 1048576):
            IN_HEIGHT, IN_WIDTH = self.scale_values(IN_HEIGHT, IN_WIDTH, 1048576)

        # Step 3: Swap IN_HEIGHT and IN_WIDTH if selected
        if IN_swap:
            IN_HEIGHT, IN_WIDTH = IN_WIDTH, IN_HEIGHT

        return IN_HEIGHT, IN_WIDTH

    def swap_and_scale(
        self,
        IN_HEIGHT,
        IN_WIDTH,
        Swap_Width_Height,
        factor_32px,
        Limit_1MP,
    ):
        """Runs the processing function and returns the updated values."""
        OUT_HEIGHT, OUT_WIDTH = self.process_inputs(IN_HEIGHT, IN_WIDTH, Swap_Width_Height, factor_32px, Limit_1MP)

        return OUT_HEIGHT, OUT_WIDTH


    @classmethod
    def execute(cls, IN_HEIGHT, IN_WIDTH, Swap_Width_Height, factor_32px, Limit_1MP) -> io.NodeOutput:
        # The original is stateless; retain its complete computation unchanged.
        return io.NodeOutput(*cls().swap_and_scale(
            IN_HEIGHT, IN_WIDTH, Swap_Width_Height, factor_32px, Limit_1MP,
        ))


NODE_CLASS_MAPPINGS = {
    "SwapAndScale": SwapAndScale,
}

NODE_DISPLAY_NAME_MAPPINGS = {
    "SwapAndScale": "Swap width/height and/or scale image",
}


class SwapAndScaleExtension(ComfyExtension):
    async def get_node_list(self) -> list[type[io.ComfyNode]]:
        return [SwapAndScale]


async def comfy_entrypoint() -> ComfyExtension:
    return SwapAndScaleExtension()

"""TEST-only scalar observer; never part of the production SwapAndScale pack."""
import torch
from comfy_api.latest import io


class MervynSwapAndScaleScalarTestObserver(io.ComfyNode):
    SDK_REFS = False
    SDK_PERMISSIONS = ()

    @classmethod
    def define_schema(cls):
        return io.Schema(
            node_id="MervynSwapAndScaleScalarTestObserver",
            category="tests/SwapAndScale",
            inputs=[
                io.Int.Input("actual_height"),
                io.Int.Input("actual_width"),
                io.Int.Input("expected_height"),
                io.Int.Input("expected_width"),
            ],
            outputs=[io.Image.Output()],
        )

    @classmethod
    def execute(cls, actual_height, actual_width, expected_height, expected_width):
        if any(type(value) is not int for value in (
            actual_height, actual_width, expected_height, expected_width,
        )):
            raise AssertionError("SwapAndScale TEST observer requires strict integers")
        if (expected_height, expected_width) != (704, 1440):
            raise AssertionError("SwapAndScale TEST observer literals changed")
        if (actual_height, actual_width) != (expected_height, expected_width):
            raise AssertionError("SwapAndScale TEST scalar result differs")
        image = torch.empty((1, 64, 64, 3), dtype=torch.float32, device="cpu")
        image[..., 0] = 0x12 / 255
        image[..., 1] = 0x34 / 255
        image[..., 2] = 0x56 / 255
        return io.NodeOutput(image)
